#include <stdio.h>

/* teste do desafio a-porta-secreta — counter_protocol (03-tdd 3.9.3).
   Quem DIGITA e o teste: fopen/fprintf escrevem num arquivo o que o aluno
   digitaria, o freopen troca o stdin por esse arquivo, e a captura do stdout
   acontece dentro do proprio cenario (freopen + fflush, sem fclose no stdout).
   Tres cenarios: a palavra certa, uma palavra diferente e uma palavra que
   COMECA igual — nenhuma frase fixa no codigo passa nos tres. */

/* prototipo da funcao do aluno (o teste declara o que exercita) */
void aPortaSecreta(void);

SM_TEST(a_palavra_certa_abre) {
    FILE *digitado = fopen("sm_entrada_1.tmp", "w");
    fprintf(digitado, "abrir\n");
    fclose(digitado);
    freopen("sm_entrada_1.tmp", "r", stdin);

    freopen("sm_saida_1.tmp", "w", stdout);
    aPortaSecreta();
    fflush(stdout);

    FILE *f = fopen("sm_saida_1.tmp", "r");
    char linha[80] = "(nada impresso)";
    fgets(linha, 80, f);
    checa_str("a palavra certa abre", linha, "porta aberta\n",
              "abrir e a palavra secreta: a comparacao devolve zero e a porta abre");
    char fim[80] = "(nada impresso)";
    fgets(fim, 80, f);
    checa_str("nao ha linha a mais", fim, "(nada impresso)",
              "a saida e uma linha so: nenhuma linha extra e aceita");
    fclose(f);
}

