#include <stdio.h>
#include <string.h>

void aPortaSecreta(void) {
    char palavra[50] = "";
    scanf("%49s", palavra);
    if (strcmp(palavra, "abrir") == 0) {
        printf("porta aberta\n");
    } else {
        printf("porta trancada\n");
    }
}
